import{_ as a,c as t,o as i,aj as r}from"./chunks/framework.CDhdelVI.js";const g=JSON.parse('{"title":"Detroit Style Pan Pizza","description":"A Detroit style pan pizza with crisp fried edges, caramelized cheese walls, and a soft open crumb.","frontmatter":{"title":"Detroit Style Pan Pizza","description":"A Detroit style pan pizza with crisp fried edges, caramelized cheese walls, and a soft open crumb.","head":[["meta",{"name":"description","content":"A Detroit style pan pizza with crisp fried edges, caramelized cheese walls, and a soft open crumb."}],["meta",{"property":"og:title","content":"Detroit Style Pan Pizza"}],["meta",{"property":"og:description","content":"A Detroit style pan pizza with crisp fried edges, caramelized cheese walls, and a soft open crumb."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:url","content":"https://kitchenratio.com/recipes/detroit-style-pan-pizza.html"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Detroit Style Pan Pizza"}],["meta",{"name":"twitter:description","content":"A Detroit style pan pizza with crisp fried edges, caramelized cheese walls, and a soft open crumb."}],["link",{"rel":"canonical","href":"https://kitchenratio.com/recipes/detroit-style-pan-pizza.html"}]]},"headers":[],"relativePath":"recipes/detroit-style-pan-pizza.md","filePath":"recipes/detroit-style-pan-pizza.md"}'),n={name:"recipes/detroit-style-pan-pizza.md"};function l(o,e,s,d,h,c){return i(),t("div",null,[...e[0]||(e[0]=[r('<h1 id="detroit-style-pan-pizza" tabindex="-1">Detroit Style Pan Pizza <a class="header-anchor" href="#detroit-style-pan-pizza" aria-label="Permalink to “Detroit Style Pan Pizza”">​</a></h1><p>This one is about contrast: fried bottom, lacy cheese edge, and a soft interior that still has structure. The pan and oil are not optional details. They are the method. Use the <a href="https://kitchenratio.com/calculator" target="_blank" rel="noreferrer">KitchenRatio Calculator</a> to scale any batch size.</p><div class="info custom-block"><p class="custom-block-title">Testing Status</p><p>This formula is still being tested and refined.</p></div><h2 id="baker-s-testing-range" tabindex="-1">Baker&#39;s % (Testing Range) <a class="header-anchor" href="#baker-s-testing-range" aria-label="Permalink to “Baker&#39;s % (Testing Range)”">​</a></h2><ul><li><strong>Flour</strong> - 100%</li><li><strong>Water</strong> - 68-72%</li><li><strong>Salt</strong> - 2-2.5%</li><li><strong>Olive oil (in dough)</strong> - 2-3%</li><li><strong>Sugar</strong> - 1-2%</li><li><strong>Yeast (IDY)</strong> - 0.4-0.8%</li><li><strong>Pan oil</strong> - heavy, usually 10-20g+ per pan</li></ul><h2 id="ingredients-example-batch" tabindex="-1">Ingredients (Example Batch) <a class="header-anchor" href="#ingredients-example-batch" aria-label="Permalink to “Ingredients (Example Batch)”">​</a></h2><ul><li><strong>Flour</strong> - 500g (100%)</li><li><strong>Water</strong> - 350g (70%)</li><li><strong>Salt</strong> - 11g (2.2%)</li><li><strong>Olive oil (in dough)</strong> - 12.5g (2.5%)</li><li><strong>Sugar</strong> - 7.5g (1.5%)</li><li><strong>Instant dry yeast</strong> - 3g (0.6%)</li></ul><p>Need a scale? <a href="https://amzn.to/48F9DfT" target="_blank" rel="noreferrer">KitchenAid Digital Scale</a>.</p><div class="info custom-block"><p class="custom-block-title custom-block-title-default">INFO</p><p>This batch typically fits one deep 10x14-inch Detroit-style pan, or two smaller pans.</p></div><hr><h2 id="procedure" tabindex="-1">Procedure <a class="header-anchor" href="#procedure" aria-label="Permalink to “Procedure”">​</a></h2><h3 id="_1-mixing" tabindex="-1">1. Mixing <a class="header-anchor" href="#_1-mixing" aria-label="Permalink to “1. Mixing”">​</a></h3><ul><li>Combine flour, yeast, sugar, and water until no dry flour remains.</li><li>Rest 10 minutes.</li><li>Add salt and oil, then mix until cohesive.</li><li>Knead briefly, about <strong>3-4 minutes</strong>, just to smooth the dough.</li></ul><h3 id="_2-bulk-fermentation" tabindex="-1">2. Bulk Fermentation <a class="header-anchor" href="#_2-bulk-fermentation" aria-label="Permalink to “2. Bulk Fermentation”">​</a></h3><ul><li>Cover and ferment at room temperature until expanded and airy, usually <strong>2-4 hours</strong>.</li><li>For more flavor, refrigerate overnight after 60-90 minutes at room temperature.</li></ul><h3 id="_3-pan-and-first-press" tabindex="-1">3. Pan and First Press <a class="header-anchor" href="#_3-pan-and-first-press" aria-label="Permalink to “3. Pan and First Press”">​</a></h3><ul><li>Add <strong>10-20g oil</strong> to the pan and coat bottom and corners generously.</li><li>Transfer dough to pan and gently press it outward with oiled fingertips.</li><li>If it springs back, rest 10 minutes and press again.</li></ul><h3 id="_4-pan-proof" tabindex="-1">4. Pan Proof <a class="header-anchor" href="#_4-pan-proof" aria-label="Permalink to “4. Pan Proof”">​</a></h3><ul><li>Proof in pan until visibly puffy and bubbly, usually <strong>1.5-3 hours</strong> depending on temperature.</li><li>Dough should nearly fill the corners before topping.</li></ul><h3 id="_5-top-for-edge-caramelization" tabindex="-1">5. Top for Edge Caramelization <a class="header-anchor" href="#_5-top-for-edge-caramelization" aria-label="Permalink to “5. Top for Edge Caramelization”">​</a></h3><ul><li>Spread cheese all the way to the edges.</li><li>Add sauce in stripes or light spooned lines.</li><li>Keep the center balanced so it bakes through.</li></ul><h3 id="_6-bake" tabindex="-1">6. Bake <a class="header-anchor" href="#_6-bake" aria-label="Permalink to “6. Bake”">​</a></h3><ul><li>Bake at <strong>450-525F</strong> until top is browned and edge cheese is deeply caramelized, usually <strong>12-18 minutes</strong>.</li><li>If the top colors before the bottom sets, move the pan lower in the oven.</li></ul><h3 id="_7-de-pan-and-finish" tabindex="-1">7. De-pan and Finish <a class="header-anchor" href="#_7-de-pan-and-finish" aria-label="Permalink to “7. De-pan and Finish”">​</a></h3><ul><li>Run a spatula along all edges while hot.</li><li>Lift pizza out and cool on a rack for 2-3 minutes so the bottom stays crisp.</li></ul><h2 id="pan-size-and-dough-feel-starting-guide" tabindex="-1">Pan Size and Dough Feel (Starting Guide) <a class="header-anchor" href="#pan-size-and-dough-feel-starting-guide" aria-label="Permalink to “Pan Size and Dough Feel (Starting Guide)”">​</a></h2><table tabindex="0"><thead><tr><th>Pan size</th><th>Dough feel before proof</th><th>Typical bake at 475F</th></tr></thead><tbody><tr><td>8x10</td><td>Thick and pillowy</td><td>13-18 minutes</td></tr><tr><td>9x13</td><td>Balanced</td><td>12-17 minutes</td></tr><tr><td>10x14</td><td>Thinner, crisper</td><td>11-16 minutes</td></tr></tbody></table><div class="note custom-block github-alert"><p class="custom-block-title">NOTE</p><p>Dark steel pans often brown faster than light anodized pans. Trust color and crispness over the timer.</p></div><h2 id="what-to-adjust-first" tabindex="-1">What to Adjust First <a class="header-anchor" href="#what-to-adjust-first" aria-label="Permalink to “What to Adjust First”">​</a></h2><ul><li><strong>Bottom too pale</strong>: increase pan oil slightly and lower rack position.</li><li><strong>Dense interior</strong>: longer pan proof before topping.</li><li><strong>Too greasy</strong>: reduce pan oil by 2-4g, not by half.</li></ul><h2 id="related-guides" tabindex="-1">Related Guides <a class="header-anchor" href="#related-guides" aria-label="Permalink to “Related Guides”">​</a></h2><ul><li><a href="/guides/hydration.html">Hydration</a></li><li><a href="/guides/cold-fermentation.html">Cold Fermentation</a></li><li><a href="/guides/folding.html">Folding</a></li></ul><h2 id="get-the-gear" tabindex="-1">Get the Gear <a class="header-anchor" href="#get-the-gear" aria-label="Permalink to “Get the Gear”">​</a></h2><ul><li><a href="/guides/baking-gear-and-ingredients.html">Baking Gear &amp; Ingredients</a></li></ul><h2 id="related-recipes" tabindex="-1">Related Recipes <a class="header-anchor" href="#related-recipes" aria-label="Permalink to “Related Recipes”">​</a></h2><ul><li><a href="/recipes/sicilian-pan-pizza.html">Sicilian Pan Pizza</a></li><li><a href="/recipes/cold-iron-cloud-pan-pizza.html">Cold Iron Cloud Pan Pizza</a></li></ul><hr><blockquote><p><strong>Affiliate Disclaimer</strong> This post contains affiliate links. As an Amazon Associate, I earn from qualifying purchases. If you click on a link and make a purchase, I may receive a small commission at no extra cost to you.</p></blockquote>',38)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
